settings.custom_css:
/* ── 좌측 레일 — 시안 Figma 17917:61025 를 그대로 옮긴 것 ── */

/* 카테고리 내비: 항목 간격 10px, 링크 패딩 제거 */
selector .tc-rail-nav .elementor-nav-menu>li{margin-bottom:10px}
selector .tc-rail-nav .elementor-nav-menu>li>a{padding:0;line-height:normal}

/* 목차: 세로선 1px + 간격 14px (시안 Vector 1) */
selector .tc-rail-toc .lwptoc{padding:0;background:none;border:0}
selector .tc-rail-toc .lwptoc_i{padding:0 0 0 14px;background:none;border:0;
  border-left:1px solid #D9D9D9;border-radius:0}
selector .tc-rail-toc .lwptoc_header{display:none}

/* 항목: 12px Medium #989898, 간격 8px */
selector .tc-rail-toc .lwptoc_itemWrap>ul{margin:0;padding:0}
selector .tc-rail-toc .lwptoc_item{margin:0 0 8px}
selector .tc-rail-toc .lwptoc_item:last-child{margin-bottom:0}
selector .tc-rail-toc .lwptoc_item>a{font-family:'Pretendard Variable',sans-serif;
  font-size:12px;font-weight:500;color:#989898;line-height:normal}
selector .tc-rail-toc .lwptoc_item>a:hover{color:#FE7E43}

/* H3 들여쓰기 16px (시안 137px 대 153px) */
selector .tc-rail-toc .lwptoc_item ul{margin:8px 0 0;padding-left:16px}

/* 레일이 뷰포트보다 길 때: 내부 스크롤. 고정 상태에서만 건다 —
   평상시에 max-height 를 걸면 짧은 화면에서 문서 흐름이 이상해진다. */
selector.elementor-sticky--active{
  max-height:calc(100vh - 120px);
  overflow-y:auto;overscroll-behavior:contain;
  scrollbar-width:thin;scrollbar-color:#D9D9D9 transparent}
selector.elementor-sticky--active::-webkit-scrollbar{width:4px}
selector.elementor-sticky--active::-webkit-scrollbar-thumb{
  background:#D9D9D9;border-radius:2px}

/* ul 기본 패딩 제거 — 시안은 텍스트가 그리드 왼쪽에 붙는다 */
selector .tc-rail-nav .elementor-nav-menu{padding-left:0;margin:0}

/* 스티키 z-index — 헤더(99)보다 아래로. 부모 끝에 밀려 올라갈 때
   헤더·로고 위로 그려지는 겹침 방지 */
selector.elementor-sticky--active{z-index:89}

/* 시안 17917:61068 — 아바타(40) 뒤로 열들이 내용 폭만큼, 간격 20px.
   퍼센트 컬럼을 쓰면 전체 폭에 분산되므로 자동 폭으로 바꾼다. */
selector > .elementor-container{justify-content:flex-start}
selector .elementor-column{width:auto!important;flex:0 0 auto}
selector .elementor-column + .elementor-column{margin-left:20px}
selector .elementor-widget-wrap{align-content:center;align-items:center}
/* 라벨-값 간격 4px (시안 17917:61070) */
selector .tc-meta-label{margin-bottom:4px!important}
selector .tc-meta-avatar img{width:40px;height:40px;object-fit:cover;border-radius:50%}
